@media screen and (max-width: 768px) {
	.App.library-active {
		margin-right: 0;
	}

	.mini-video-shell {
		left: 0.75rem;
		top: 0.75rem;
		width: min(calc(100vw - 1.5rem), 22.5rem);
	}

	.record {
		width: min(72vw, 18rem);
	}

	.play-control {
		width: min(80%, 18rem);
	}

	.library {
		width: 100%;
	}
}

