@media screen and (max-width: 640px) {
	.song-container h2 {
		font-size: 1.35rem;
		line-height: 1.15;
		max-width: 20rem;
		overflow-wrap: anywhere;
		white-space: normal;
		width: 20rem;
	}

	.time-control {
		max-width: 18rem;
		width: 18rem;
	}

	.time-control p {
		min-width: 2.5rem;
		text-align: center;
	}

	.youtube-disclosure {
		display: block;
		max-width: 20rem;
		padding-inline: 1rem;
	}

	.youtube-disclosure span {
		display: block;
		overflow-wrap: anywhere;
	}

	.youtube-disclosure a {
		display: inline-block;
		margin: 0.55rem 0.35rem 0;
	}
}

